function faceDownPrivateKey(ref){return'mtgte_fd_private_'+String(ref||'')}
function storeFaceDownPrivate(card,mechanism){let ref='fdref_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,10),safe=typeof MTGDeckEngine!=='undefined'?MTGDeckEngine.publicCardRecord(card):card;try{localStorage.setItem(faceDownPrivateKey(ref),JSON.stringify({card:safe,mechanism:String(mechanism||''),room:activeRoom||null,playerId:me,at:Date.now()}))}catch{}return ref}
