function faceDownCardMechanisms(card={}){let text=String(card.oracleText||card.oracle_text||''),out=[];if(/(?:^|\n)\s*Megamorph\s+/i.test(text))out.push('megamorph');if(/(?:^|\n)\s*Morph\s+/i.test(text))out.push('morph');if(/(?:^|\n)\s*Disguise\s+/i.test(text))out.push('disguise');return out}
function chooseFaceDownCast(){let cards=(prof.cards||[]).map(c=>({card:c,mechs:faceDownCardMechanisms(c)})).filter(x=>x.mechs.length);if(!cards.length)return toast('No Morph, Megamorph, or Disguise cards are loaded in this deck.');choice(cards.map((x,i)=>(i+1)+' · '+x.card.n+' · '+x.mechs.map(m=>m.toUpperCase()).join('/')),pick=>{let x=cards[parseInt(pick,10)-1];if(!x)return;let chooseMech=cb=>x.mechs.length===1?cb(x.mechs[0]):choice(x.mechs.map(m=>m.toUpperCase()),m=>cb(String(m).toLowerCase()));chooseMech(mech=>{let ref=storeFaceDownPrivate(x.card,mech),pub=MTGFaceDownMechanics.castPublicCard(mech);cmd('cast',{n:pub.n,cardPublic:pub,faceDownState:{mechanism:mech,privateIdentityRef:ref,origin:'cast-face-down',castFaceDown:true},fromZone:'hand'})})})}
function chooseManifestOrCloak(){let cards=prof.cards||[];if(!cards.length)return toast('Load a deck first so the hidden card can stay private on this device.');choice(['Manifest a card','Cloak a card'],kind=>{let mech=kind.startsWith('Cloak')?'cloak':'manifest';choice(cards.map((c,i)=>(i+1)+' · '+c.n),pick=>{let card=cards[parseInt(pick,10)-1];if(!card)return;let ref=storeFaceDownPrivate(card,mech),oid='fd_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,8);cmd('faceDownEnter',{objectId:oid,mechanism:mech,privateIdentityRef:ref,origin:mech})})})}
function revealCardForFaceDownObject(o){let saved=loadFaceDownPrivate(o?.faceDownState?.privateIdentityRef||o?.formState?.privateIdentityRef);if(saved?.card)return saved.card;let n=prompt('Reveal card name');if(!n)return null;let c=prof.cardMap?.get(String(n).toLowerCase());return c?(typeof MTGDeckEngine!=='undefined'?MTGDeckEngine.publicCardRecord(c):c):null}
function turnFaceDownObjectUp(o){if(!o||!o.faceDownState?.active)return;let reveal=revealCardForFaceDownObject(o);if(!reveal)return toast('The revealed card could not be matched to the loaded deck.');let routes=MTGFaceDownMechanics.turnUpRoutes(reveal,o.faceDownState.mechanism);if(!routes.length)return toast('No legal tracked turn-face-up route was proven for that card.');let chooseRoute=cb=>routes.length===1?cb(routes[0]):choice(routes.map((r,i)=>(i+1)+' · '+r.route.toUpperCase()+' · '+r.cost),pick=>cb(routes[parseInt(pick,10)-1]));chooseRoute(r=>{if(!r)return;let x=null;if(/\{X\}/i.test(r.cost)){let raw=prompt('Value of X','0');if(raw===null)return;x=Number(raw);if(!Number.isFinite(x)||x<0)return toast('X must be zero or greater.')}if(!confirm('Confirm you paid '+r.cost+' to turn this permanent face up.'))return;cmd('faceUpSpecial',{objectId:o.id,reveal,route:r.route,paymentConfirmed:true,xValue:x})})}
