function castAdventureChoice(row){if(!row||typeof MTGCastPermissions==='undefined')return;let publicCard=MTGCastPermissions.adventureStackCard(row.card),state=MTGCastPermissions.adventureCastState(row.card);if(!publicCard||!state)return toast('Adventure faces could not be verified.');cmd('cast',{n:publicCard.n,cardPublic:publicCard,fromZone:'hand',adventureState:state})}
