async function prepareExileAction(){if(typeof MTGPreparedExile==='undefined')return toast('Prepared-exile module unavailable.');choice(['Foretell a Card','Plot a Card','Suspend a Card'],async mode=>{let name=prompt(mode==='Foretell a Card'?'Exact card name to foretell:':mode==='Plot a Card'?'Exact card name to plot:':'Exact card name to suspend:','');if(!name)return;toast('Checking '+name+'…');let card=await phase101LookupCard(name.trim());if(!card)return toast('Card lookup failed. Check the exact card name and connection.');let objectId='prepared_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,8);if(mode==='Suspend a Card'){if(typeof MTGSuspend==='undefined')return toast('Suspend module unavailable.');let sp=MTGSuspend.parse(card);if(!sp)return toast('A supported printed Suspend N—cost definition was not found. Use Rules Review for granted/dynamic suspend.');if(!confirm('Pay '+sp.cost+' and exile '+card.n+' with '+sp.time+' time counter'+(sp.time===1?'':'s')+'?'))return;cmd('prepareSuspend',{objectId,cardPublic:MTGDeckEngine.publicCardRecord(card),paymentConfirmed:true});return}if(mode==='Foretell a Card'){let cost=MTGPreparedExile.foretellCost(card);if(!cost)return toast('A supported printed Foretell cost was not found. Use Rules Review for granted/dynamic foretell.');if(!confirm('Pay {2} and exile '+card.n+' face down with foretell? The app will keep its identity private until you cast it.'))return;let ref='private_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,12);if(!phase101SavePrivate(ref,MTGDeckEngine.publicCardRecord(card)))return toast('Private session storage is unavailable. Foretell was not recorded.');cmd('prepareForetell',{objectId,privateIdentityRef:ref,paymentConfirmed:true});return}let cost=MTGPreparedExile.plotCost(card);if(!cost)return toast('A supported printed Plot cost was not found. Use Rules Review for alternate plot instructions.');if(!confirm('Pay '+cost+' and exile '+card.n+' face up as plotted?'))return;cmd('preparePlot',{objectId,cardPublic:MTGDeckEngine.publicCardRecord(card),paymentConfirmed:true})})}
async function preparePhase103AlternateCast(){if(typeof MTGAlternateZoneCasting==='undefined')return toast('Phase 104 alternate-zone module unavailable.');choice(['Flashback from Graveyard','Escape from Graveyard','Disturb from Graveyard','Retrace from Graveyard','Jump-start from Graveyard','Aftermath from Graveyard','Discard with Madness','Cast with Warp'],async mode=>{if(['Flashback from Graveyard','Escape from Graveyard','Disturb from Graveyard','Retrace from Graveyard','Jump-start from Graveyard','Aftermath from Graveyard'].includes(mode)){let zone=st.zones?.graveyard||[];if(!zone.length)return toast('No individually tracked cards are in your graveyard.');let name=prompt('Exact graveyard card name:');if(!name)return;let matches=zone.filter(o=>String(o.name||'').toLowerCase()===String(name).trim().toLowerCase());if(!matches.length)return toast('Track that exact card in the graveyard first.');let source=matches[0];if(matches.length>1){let labels=matches.map((o,i)=>(i+1)+'. '+o.name+' · '+String(o.id).slice(-6)),raw=prompt('Multiple copies are tracked. Enter the number to use:\n'+labels.join('\n'),'1'),at=Math.max(0,Number(raw||1)-1);source=matches[at];if(!source)return toast('No copy selected.')}let card=source.phase100CardPublic||await phase101LookupCard(source.name);if(!card)return;if(mode==='Flashback from Graveyard'){if(!MTGAlternateZoneCasting.parseFlashback(card))return toast('A supported Flashback cost was not found on that card.');cmd('phase103Flashback',{objectId:source.id,cardPublic:card});return}if(mode==='Disturb from Graveyard'){if(!MTGAlternateZoneCasting.parseDisturb(card))return toast('A supported Disturb back-face cast was not found on that card.');cmd('phase104Disturb',{objectId:source.id,cardPublic:card});return}if(mode==='Retrace from Graveyard'){if(!MTGAlternateZoneCasting.parseRetrace(card))return toast('Retrace was not found on that card.');cmd('phase104Retrace',{objectId:source.id,cardPublic:card});return}if(mode==='Jump-start from Graveyard'){if(!MTGAlternateZoneCasting.parseJumpStart(card))return toast('Jump-start was not found on that card.');cmd('phase104JumpStart',{objectId:source.id,cardPublic:card});return}if(mode==='Aftermath from Graveyard'){if(!MTGAlternateZoneCasting.parseAftermath(card))return toast('A supported Aftermath half was not found on that card.');cmd('phase104Aftermath',{objectId:source.id,cardPublic:card});return}let parsed=MTGAlternateZoneCasting.parseEscape(card);if(!parsed)return toast('A supported Escape cost was not found on that card.');let candidates=zone.filter(o=>String(o.id)!==String(source.id));if(candidates.length<parsed.count)return toast('Not enough individually tracked other graveyard cards for this Escape cost.');let list=candidates.map((o,i)=>(i+1)+'. '+(o.name||'Card')+' · '+String(o.id).slice(-6)),raw=prompt('Escape requires exactly '+parsed.count+' other graveyard card'+(parsed.count===1?'':'s')+'.\nEnter '+parsed.count+' numbers separated by commas:\n'+list.join('\n'));if(!raw)return;let picks=[...new Set(raw.split(',').map(x=>Number(x.trim())-1).filter(x=>Number.isInteger(x)&&x>=0&&x<candidates.length))];if(picks.length!==parsed.count)return toast('Select exactly '+parsed.count+' different cards.');cmd('phase103Escape',{objectId:source.id,cardPublic:card,paymentObjectIds:picks.map(i=>candidates[i].id)});return}
let name=prompt(mode==='Discard with Madness'?'Exact card name being discarded with Madness:':'Exact card name to cast using Warp:');if(!name)return;let card=await phase101LookupCard(name);if(!card)return;if(mode==='Discard with Madness'){if(!MTGAlternateZoneCasting.parseMadness(card))return toast('A supported Madness cost was not found on that card.');cmd('phase103Madness',{objectId:'madness_'+Date.now().toString(36),cardPublic:card});return}if(!MTGAlternateZoneCasting.parseWarp(card))return toast('A supported Warp cost was not found on that card.');cmd('phase103Warp',{cardPublic:card})})}
function runPhase103AlternateZoneQA(){if(!soloTestMode)return toast('Phase 104 QA is available in Solo Test.');if(typeof MTGAlternateZoneCasting==='undefined')return toast('Phase 104 module is unavailable.');let r=MTGAlternateZoneCasting.localQA(MTGEngine),failed=(r.checks||[]).filter(x=>!x[1]);$('modal').classList.remove('profileHubModal');$('choices').innerHTML='<div class="whySheet"><div class="small">PHASE 104 · GRAVEYARD / ALTERNATE CASTING QA</div><div class="whyTitle">'+(r.ok?'PASS':'REVIEW')+'</div><div class="whySteps">'+(r.checks||[]).map(x=>'<div class="whyStep"><b>'+(x[1]?'✓':'!')+'</b><span>'+esc(x[0])+'</span></div>').join('')+'</div>'+(failed.length?'<div class="hostWarn" style="margin-top:10px">'+failed.length+' check(s) need review.</div>':'<div class="hostMuted" style="margin-top:10px">Flashback, Escape, Madness, Warp, Disturb, Retrace, Jump-start, Aftermath, Rebound, exact incarnation binding, destination rules, and reconnect state passed.</div>')+'</div>';$('modal').classList.remove('h')}
