function runContextAction(id){wakePlayerHud(30000);if(id==='cast'||id==='add-stack'){let normal=(prof.cards||[]).filter(x=>!/(^|—)\s*land\b/i.test(x.typeLine||'')).map(x=>x.n),fd=(prof.cards||[]).some(c=>faceDownCardMechanisms(c).length),adventure=adventureCastChoices(),labels=normal.concat(adventure.map(x=>x.label),fd?['FACE DOWN · MORPH / MEGAMORPH / DISGUISE']:[]);return choice(labels,n=>{if(n==='FACE DOWN · MORPH / MEGAMORPH / DISGUISE')return chooseFaceDownCast();let ar=adventure.find(x=>x.label===n);if(ar)return castAdventureChoice(ar);let commanderIdentity=localCommanderIdentity(n,me);cmd('cast',{n,cardPublic:publicCardForCast(n),commander:!!commanderIdentity,...(commanderIdentity?{commanderId:commanderIdentity.commanderId,fromZone:'command'}:{})})})}if(id==='respond'||id==='activate')return respondQuick();if(id==='pass')return passQuick();if(id==='combat-ready'||id==='next-phase')return cmd('advanceTurn',{});if(id==='wait')return toast('Waiting for the current priority holder.');if(id==='quick')return quickActionMenu();if(id==='land')return playLandQuick();if(id==='attack'||id==='counter')return combatQuick();if(id==='damage')return recordDamage();if(id==='inspect')return inspectStackQuick();return moreQuick()}
function renderPlayerAlerts(){if(typeof MTGPlayerAlerts==='undefined'||!$('game'))return;let hud=document.querySelector('.playerHud'),banner=$('hudCriticalBanner');if(!hud||!banner)return;if(!hudFlags.criticalStateAwareness){hud.removeAttribute('data-life-band');hud.removeAttribute('data-poison-band');hud.removeAttribute('data-commander-band');hud.classList.remove('lastStandHud','criticalHud');banner.className='hudCriticalBanner h';banner.textContent='';lastPlayerAlertStatus=null;return}let matchId=st.meta?.matchId||'local';if(lastPlayerAlertMatchId!==matchId){lastPlayerAlertStatus=null;lastPlayerAlertMatchId=matchId}let current=MTGPlayerAlerts.evaluate(st,me),changes=MTGPlayerAlerts.transition(lastPlayerAlertStatus,current);hud.dataset.lifeBand=current.lifeBand;hud.dataset.poisonBand=current.poisonBand;hud.dataset.commanderBand=current.commanderBand;hud.classList.toggle('lastStandHud',current.lastStand);hud.classList.toggle('criticalHud',current.critical);let label='',detail='';if(current.lastStand){label='LAST STAND';detail=current.reasons.map(x=>x.label).join(' · ')}else if(current.poison>=8){label='POISON DANGER';detail=current.poison+' / 10'}else if(current.commanderDamage>=18){label='COMMANDER DAMAGE';detail=current.commanderDamage+' / 21 · '+current.commanderRemaining+' REMAINING'}else if(current.life<=10){label='LOW LIFE';detail=current.life+' LIFE'}if(label){banner.classList.remove('h');banner.innerHTML='<b>'+esc(label)+'</b><span>'+esc(detail)+'</span>'}else{banner.classList.add('h');banner.textContent=''}if(changes.length){banner.classList.remove('attentionPulse');void banner.offsetWidth;banner.classList.add('attentionPulse');let top=changes[0];if(top.id==='last-stand')toast('LAST STAND · '+top.detail);else if(top.id==='recovered')toast('SECOND WIND')}lastPlayerAlertStatus=current}
