function setPlayerHudPage(page){page=(typeof MTGPlayerPages!=='undefined'?MTGPlayerPages.normalizePage(page):String(page||'home'));playerHudPage=page;[['home','playerHomePage'],['battlefield','playerBattlefieldPage'],['log','playerLogPage']].forEach(([k,id])=>$(id)?.classList.toggle('h',k!==page));document.querySelectorAll('[data-player-page]').forEach(b=>b.classList.toggle('active',b.dataset.playerPage===page));let dock=$('game')?.querySelector('.contextualDock'),hint=$('contextHint');if(dock)dock.classList.toggle('h',page!=='home');if(hint)hint.classList.toggle('h',page!=='home');if(page==='battlefield'){renderBattlefieldPlayerTabs();renderSpatialBattlefieldOverview();renderBattlefieldBoardSummary()}if(page==='log')logs();}
function renderBattlefieldPlayerTabs(){let mount=$('battlefieldPlayerTabs');if(!mount||typeof MTGPlayerPages==='undefined')return;let tabs=[{id:'all',name:'ALL'}].concat(MTGPlayerPages.playerTabs(players,me));mount.innerHTML=tabs.map(p=>'<button class="battlefieldPlayerTab '+(String(battlefieldViewPlayer)===String(p.id)?'active':'')+'" data-bf-player="'+esc(p.id)+'">'+esc(p.name)+(p.self?' · YOU':'')+'</button>').join('');mount.querySelectorAll('[data-bf-player]').forEach(b=>b.onclick=()=>{battlefieldViewPlayer=b.dataset.bfPlayer==='all'?'all':Number(b.dataset.bfPlayer);renderBattlefieldPlayerTabs();battle()});let label=$('battlefieldViewerLabel'),pl=players.find(p=>Number(p.id)===Number(battlefieldViewPlayer));if(label)label.innerHTML=battlefieldViewPlayer==='all'?'<b>Spatial table overview</b> · choose a player to inspect battlefield and public zones.':'Viewing <b>'+esc(pl?.name||('Player '+battlefieldViewPlayer))+'</b> · battlefield, commander-in-play slot, lands, library count, graveyard and exile.';renderSpatialBattlefieldOverview();renderBattlefieldBoardSummary()}
function renderSpatialBattlefieldOverview(){let m=$('battlefieldSpatialOverview');if(!m||typeof MTGBattlefieldBoard==='undefined')return;let laid=typeof MTGSpatialOpponents!=='undefined'?MTGSpatialOpponents.layout(players,me,spatialSeatMap):players.map(p=>({...p,spatialSlot:Number(p.id)===Number(me)?'you':'flat'}));let self=players.find(p=>Number(p.id)===Number(me));if(self&&!laid.some(p=>Number(p.id)===Number(me)))laid.push({...self,spatialSlot:'you'});m.innerHTML=laid.map(p=>{let slot=Number(p.id)===Number(me)?'you':(p.spatialSlot||'flat'),life=st.life[p.id]??40,poison=st.poison[p.id]||0,cmdMax=0;for(const v of Object.values(st.cmd?.[p.id]||{}))cmdMax=Math.max(cmdMax,Number(v)||0);let av=avatarMarkup(p.avatarId||MTGAvatars.DEFAULT_ID,{compact:true});return '<button class="bfSeat bfSeatShortcut '+(Number(battlefieldViewPlayer)===Number(p.id)?'active':'')+'" data-bf-seat="'+p.id+'" data-slot="'+esc(slot)+'"><div class="bfSeatAvatar avatarMount">'+av+'</div><div class="bfSeatIdentity"><div class="bfSeatName">'+esc(p.name||('Player '+p.id))+(Number(p.id)===Number(me)?' · YOU':'')+'</div><div class="bfSeatCommander">'+esc(p.commander||'Commander')+'</div></div><div class="bfSeatVitals"><b>'+life+'</b><span>LIFE</span></div><div class="bfSeatPublic"><span>POISON '+poison+'</span><span>CMD MAX '+cmdMax+'</span></div><div class="bfSeatHint">TAP TO VIEW BATTLEFIELD</div></button>'}).join('');m.querySelectorAll('[data-bf-seat]').forEach(b=>b.onclick=()=>{battlefieldViewPlayer=Number(b.dataset.bfSeat);renderBattlefieldPlayerTabs();renderSpatialBattlefieldOverview();renderBattlefieldBoardSummary();document.getElementById('battlefieldBoardSummary')?.scrollIntoView({behavior:'smooth',block:'start'})})}
async function inspectPublicCard(objectId){let o=st.battle.find(x=>String(x.id)===String(objectId));if(!o)return;let snap=typeof MTGPlayerPages!=='undefined'?MTGPlayerPages.publicCardSnapshot(o):{name:o.name,type:o.type||'Permanent',quantity:o.q||'1',tapped:!!o.tapped};$('modal').classList.remove('h');$('choices').innerHTML='<div class="whySheet"><div class="small">PUBLIC CARD REFERENCE</div><div class="cardRulesTitle">'+esc(snap.name)+'</div><div class="cardRulesType">Loading current Oracle text…</div><div class="cardRulesText">Looking up this public battlefield card.</div><div class="cardRulesMeta"><span>'+(snap.tapped?'TAPPED':'UNTAPPED')+'</span><span>×'+esc(snap.quantity||'1')+'</span></div></div>';try{let url=MTGPlayerPages.scryfallNamedUrl(snap.name),r=await fetch(url);if(!r.ok)throw new Error('lookup');let c=await r.json(),type=document.querySelector('.cardRulesType'),text=document.querySelector('.cardRulesText');if(type)type.textContent=c.type_line||snap.type||'Card';if(text)text.textContent=c.oracle_text||'No Oracle text is listed for this card.'}catch(e){let type=document.querySelector('.cardRulesType'),text=document.querySelector('.cardRulesText');if(type)type.textContent=snap.type||'Public battlefield card';if(text)text.textContent='Oracle text is unavailable right now. The card name and tracked public battlefield state remain available offline.'}}
