function showAssistWhy(item){if(!item||typeof MTGAssistMode==='undefined')return;markAssistSeen(item.key);let x=MTGAssistMode.explain(item);$('modal').classList.remove('h');$('choices').innerHTML='<div class="whySheet"><div class="small">PHASE 81 · ASSIST EXPLANATION</div><div class="whyTitle">'+esc(x.title)+'</div><div class="assistCoachBadges" style="justify-content:flex-start;margin-top:8px"><span class="assistCoachBadge '+esc(x.attention)+'">'+esc(x.attentionLabel)+'</span><span class="assistCoachBadge '+esc(x.confidence)+'">'+esc(x.confidenceLabel)+'</span><span class="assistCoachBadge">READ-ONLY</span></div><div class="assistReference">SOURCE · '+esc(x.referenceLabel)+'</div><div class="assistWhyList">'+x.why.map(w=>'<div class="assistWhyFact">'+esc(w)+'</div>').join('')+'</div><div class="hostMuted">Assist only explains public tracked state or your private local deck profile. It never performs PASS, target, mode, combat, or replacement-effect choices.</div></div>'}
function showAssistQueue(view){if(!view?.items?.length)return;$('modal').classList.remove('h');$('choices').innerHTML='<div class="whySheet"><div class="small">PHASE 81 · PRIVATE ASSIST QUEUE</div><div class="whyTitle">'+view.items.length+' reminders</div><div class="hostMuted">Highest priority is shown first. Required attention stays until the underlying state clears.</div>'+view.items.map((x,i)=>'<div class="assistQueueItem"><div class="assistQueueHead"><div class="assistQueueTitle">'+esc(x.title)+'</div><div class="assistQueueMeta">'+esc(x.attentionLabel)+' · '+esc(x.confidenceLabel)+'</div></div><div class="assistCoachDetail">'+esc(x.detail)+'</div><div class="assistReference">'+esc(MTGAssistMode.refLabel(x.reference))+'</div><div class="assistCoachActions"><button class="assistCoachWhy" data-assist-queue-why="'+i+'">WHY?</button><button class="assistCoachAction" data-assist-queue-action="'+i+'">'+esc(x.actionLabel||'REVIEW')+'</button></div></div>').join('')+'</div>';document.querySelectorAll('[data-assist-queue-why]').forEach(b=>b.onclick=()=>showAssistWhy(view.items[Number(b.dataset.assistQueueWhy)]));document.querySelectorAll('[data-assist-queue-action]').forEach(b=>b.onclick=()=>{let x=view.items[Number(b.dataset.assistQueueAction)];$('modal').classList.add('h');handleAssistAction(x.action,x)})}
function renderAssistCoach(){let mount=$('assistCoach');if(!mount||typeof MTGAssistMode==='undefined')return;let v=MTGAssistMode.evaluate({enabled:assistEnabled(),state:st,players,playerId:me,profile:prof,dismissedKeys:Object.keys(assistHistory.dismissed||{}),seenKeys:Object.keys(assistHistory.seen||{})});mount.classList.toggle('h',!v.show);if(!v.show){mount.innerHTML='';mount.removeAttribute('data-assist-kind');return}mount.dataset.assistKind=v.kind||'reminder';mount.classList.toggle('urgent',!!v.urgent);mount.classList.toggle('priority',v.kind==='priority');let source=MTGAssistMode.refLabel(v.reference),dismiss=v.attention==='convenience'?'<button class="assistCoachDismiss" data-assist-dismiss="'+esc(v.key||'')+'">DISMISS</button>':'';mount.innerHTML='<div class="assistCoachTop"><div class="assistCoachTitle">'+esc(v.title)+'</div><div class="assistCoachBadges"><span class="assistCoachBadge '+esc(v.attention)+'">'+esc(v.attentionLabel)+'</span><span class="assistCoachBadge '+esc(v.confidence)+'">'+esc(v.confidenceLabel)+'</span><span class="assistCoachBadge">READ-ONLY</span></div></div><div class="assistCoachDetail">'+esc(v.detail)+'</div><div class="assistCoachSource">SOURCE · '+esc(source)+'</div><div class="assistCoachActions"><button class="assistCoachAction" data-assist-action="'+esc(v.action||'open-controls')+'">'+esc(v.actionLabel||'REVIEW')+'</button><button class="assistCoachWhy" data-assist-why="1">WHY?</button>'+(v.moreCount?'<button class="assistCoachMore" data-assist-more="1">MORE · '+v.moreCount+'</button>':'')+dismiss+'</div>';mount.querySelector('[data-assist-action]')?.addEventListener('click',()=>handleAssistAction(v.action,v));mount.querySelector('[data-assist-why]')?.addEventListener('click',()=>showAssistWhy(v));mount.querySelector('[data-assist-more]')?.addEventListener('click',()=>showAssistQueue(v));mount.querySelector('[data-assist-dismiss]')?.addEventListener('click',e=>{dismissAssistKey(e.currentTarget.dataset.assistDismiss);renderAssistCoach()})}
function runAssistModeQA(){if(typeof MTGAssistMode==='undefined')return toast('Assist Mode module unavailable.');let q=MTGAssistMode.localQA();$('modal').classList.remove('h');$('choices').innerHTML='<div class="whySheet"><div class="small">PHASE 81 · LOCAL QA</div><div class="whyTitle">Assist Mode '+(q.ok?'PASS':'FAIL')+'</div><div class="hostMuted" style="margin:8px 0">Confidence, reasons, grouping and local history are private/read-only. No PASS, target, mode, or game-state choice is executed automatically.</div>'+q.checks.map(x=>'<div class="historyMatch"><span><b>'+esc(x[0])+'</b></span><strong>'+(x[1]?'✓':'!')+'</strong></div>').join('')+'</div>';toast(q.ok?'Assist Mode QA passed.':'Assist Mode QA found a failure.')}
